import numpy as np
import timeit

problem = (np.random.randn(1000), np.random.randn(1000))

# Method 1: unpack
def solve_unpack(problem):
    vec1, vec2 = problem
    return np.multiply.outer(vec1, vec2)

# Method 2: index
def solve_index(problem):
    return np.multiply.outer(problem[0], problem[1])

# Method 3: single line unpack
def solve_oneline(problem):
    return np.multiply.outer(*problem)

t1 = timeit.timeit(lambda: solve_unpack(problem), number=10000)
t2 = timeit.timeit(lambda: solve_index(problem), number=10000)
t3 = timeit.timeit(lambda: solve_oneline(problem), number=10000)
print(f'unpack: {t1:.4f}s, index: {t2:.4f}s, star: {t3:.4f}s')
print(f'unpack: {t1/10000*1e6:.2f}us, index: {t2/10000*1e6:.2f}us, star: {t3/10000*1e6:.2f}us')
"

